{
  "edits": {
    "task.tal": "struct Meter {
    level: i32
}

fn read(m: &Meter) -> i32 {
    return m.level;
}

fn raise(m: &mut Meter, amount: i32) -> i32 {
    m.level = m.level + amount;
    return m.level;
}

fn in_range(x: i32, low: i32, high: i32) -> bool {
    return (low <= x) && (x <= high);
}

fn classify(x: i32) -> i32 {
    if (x < 0) {
        return -1;
    } else {
        if (x == 0) {
            return 0;
        }
        return 1;
    }
}

fn boost(m: &mut Meter, x: i32) -> i32 {
    let before = read(&m);
    let step = classify(x) * 10;
    raise(&mut m, step);
    return read(&m) - before;
}

fn scaled(x: i32) -> i32 {
    let x2 = x * 2;
    let x3 = x2 + 3;
    return x3;
}

fn sum3(a: i32, b: i32, c: i32) -> i32 {
    let s1 = a + b;
    let s2 = s1 + c;
    return s2;
}

fn settle(m: Meter) -> i32 {
    let kept = m;
    return kept.level + kept.level;
}

fn main() -> i32 {
    let mut meter = Meter { level: 5 };
    if (boost(&mut meter, 3) != 10) {
        return 1;
    }
    return 0;
}
"
